import pandas as pd

def solve(data):
     df = pd.DataFrame(data['rows'], columns=['so_coc','don_gia'])
     df['tong_tien'] = df['so_coc'] * df['don_gia']
     df.loc[df['so_coc'] >= 3, 'tong_tien'] = data['cap']
     return df['tong_tien'].tolist()
